// A cnx function registered with a C callback typedef takes the typedef's
// shape (#895): its `Full` parameter is a `Full*` in C AND in C++, because a C
// function pointer cannot take a C++ reference. Member access honored that --
// `f->pokes` in both modes -- but a whole-value use asked the MODE instead of
// the parameter, and C++ rendered the pointer itself: `Full copy = f;`, which
// g++ rejects as a conversion from `Full*` to `Full`. The transpiler exited 0.
//
// Control: a function NOT registered with the typedef keeps ADR-006 reference
// semantics, so in C++ its parameter is a `const Full&` and a whole-value use
// stays the bare name.
#include "full_cb.h"

#include <stdint.h>

// ADR-044: Overflow helper functions
#include <limits.h>

/* ADR-044 / Issue #94: the second parameter is the WIDER type, not the value type.
   Narrowing it first would let an out-of-range operand truncate INTO range and defeat
   the check: cnx_clamp_add_u8(0, 256) must saturate to 255, but (uint8_t)256 is 0, so a
   uint8_t parameter would return 0 -- the opposite of saturation. */

static inline uint32_t cnx_clamp_add_u32(uint32_t a, uint64_t b) {
    if (b > (uint64_t)(UINT32_MAX - a)) return UINT32_MAX;
    return (uint32_t)(a + (uint32_t)b);
}

void onFull(Full* f) {
    const Full copy = (*f);
    f->pokes = cnx_clamp_add_u32(copy.pokes, 10U);
}

uint32_t plainSnapshot(const Full* f) {
    const Full copy = (*f);
    return copy.pokes;
}

int main(void) {
    Full f = { .pokes = 1U };
    full_register(onFull);
    full_invoke(&f);
    if (f.pokes != 11) {
        return 1;
    }
    const uint32_t snapshot = plainSnapshot(&f);
    if (snapshot != 11) {
        return 2;
    }
    return 0;
}
